import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'fs';
import { join } from 'path';
import { GameReplay } from './wizard/types';

// One file per game, because a replay is large and only needed when someone opens it.
// Kept only in memory if no directory is given. Game ids are generated by the server.
export class ReplayStore {
  private replays = new Map<string, GameReplay>();

  constructor(private dirPath?: string) {}

  save(gameId: string, replay: GameReplay) {
    if (!this.dirPath) {
      this.replays.set(gameId, replay);
      return;
    }

    mkdirSync(this.dirPath, { recursive: true });
    const path = join(this.dirPath, `${gameId}.json`);
    writeFileSync(`${path}.tmp`, JSON.stringify(replay));
    renameSync(`${path}.tmp`, path);
  }

  // null if the game has no replay. Results recorded before replays existed don't.
  load(gameId: string): GameReplay | null {
    if (!this.dirPath) return this.replays.get(gameId) ?? null;

    try {
      return JSON.parse(readFileSync(join(this.dirPath, `${gameId}.json`), 'utf8'));
    } catch (err: any) {
      if (err.code !== 'ENOENT') console.error(`Reading the replay of ${gameId} failed:`, err);
      return null;
    }
  }
}
